insert into public.flashcards (id, user_id, materia_id, frente, verso, serie_minima) values
  ('c6cc50df-05ca-4ef6-a0f8-28ccbfaa1712', null, '8e02fcd1-61cf-4bd9-a555-4c076a66c31a', 'O que é a regra do octeto?', 'Átomos tendem a ganhar, perder ou compartilhar elétrons até ficar com 8 elétrons na camada de valência.', '9º ano EF'),
  ('021e9140-925f-4a88-adf5-6c30853fd1ff', null, '8e02fcd1-61cf-4bd9-a555-4c076a66c31a', 'Qual a diferença entre ligação iônica e covalente?', 'Iônica: transferência de elétrons (metal e ametal). Covalente: compartilhamento de pares de elétrons (ametais).', '9º ano EF'),
  ('2c3e8574-2501-4dde-afc8-33030ee80e7b', null, '60198414-6d0a-4944-a35f-f70cef5507b3', 'Qual a fórmula de Bhaskara?', 'x = (−b ± √Δ) / 2a, com Δ = b² − 4ac.', '9º ano EF'),
  ('d50f25d5-eaec-41eb-a30c-61cf3918c642', null, '60198414-6d0a-4944-a35f-f70cef5507b3', 'O que o sinal de Δ indica numa equação do 2º grau?', 'Δ > 0: duas raízes reais diferentes. Δ = 0: uma raiz real. Δ < 0: nenhuma raiz real.', '9º ano EF'),
  ('5cacfa20-5e01-4998-a356-bc7334b13fc6', null, 'd8b7eec1-c5a8-4387-a737-a12b0b7f8d5e', 'Qual a primeira lei de Ohm?', 'U = R · i. A tensão é igual à resistência vezes a corrente.', '9º ano EF'),
  ('4938ba2b-0c13-46fe-a9cf-96e862c387b1', null, 'ade6b967-7111-4297-a03b-41579f1c7f6d', 'Onde e quando começou a Revolução Industrial?', 'Na Inglaterra, na segunda metade do século XVIII.', '9º ano EF')
insert into public.questoes (id, user_id, materia_id, assunto, nivel, instituicao, ano, enunciado, alternativas, correta, resposta_comentada, serie_minima) values
  ('feeb39e0-dd1b-4ad0-ac25-01f01553008d', null, '60198414-6d0a-4944-a35f-f70cef5507b3', 'Função do 2º grau', 'Fácil', 'Autoral', null, 'Quais são as raízes da equação x² − 5x + 6 = 0?', '[{"letra":"A","texto":"1 e 6","explicacao":"Soma 7 e produto 6. A soma precisa ser 5."},{"letra":"B","texto":"2 e 3","explicacao":"Correta. Soma 5 e produto 6."},{"letra":"C","texto":"−2 e −3","explicacao":"Soma −5. O sinal está trocado, pois a soma das raízes é −b/a = 5."},{"letra":"D","texto":"5 e 6","explicacao":"Produto 30. O produto precisa ser 6."},{"letra":"E","texto":"−1 e −6","explicacao":"Soma −7 e produto 6. A soma precisa ser 5."}]'::jsonb, 'B', 'Procure dois números com soma 5 (que é −b/a) e produto 6 (que é c/a): são 2 e 3. Conferindo por Bhaskara: Δ = 25 − 24 = 1 e x = (5 ± 1) / 2, ou seja, 3 e 2.', '9º ano EF'),
  ('bac9cbbe-09a6-4f73-a556-029732732ac5', null, '60198414-6d0a-4944-a35f-f70cef5507b3', 'Função do 2º grau', 'Médio', 'Autoral', null, 'Qual é o vértice da parábola y = x² − 6x + 5?', '[{"letra":"A","texto":"(−3, −4)","explicacao":"O sinal de x está invertido: xv = −(−6) / 2 = 3."},{"letra":"B","texto":"(6, 5)","explicacao":"Usa −b e c como se fossem as coordenadas do vértice."},{"letra":"C","texto":"(3, 4)","explicacao":"xv está certo, mas f(3) = −4, não 4."},{"letra":"D","texto":"(3, −4)","explicacao":"Correta."},{"letra":"E","texto":"(−6, 5)","explicacao":"Troca o sinal de b e usa c como ordenada."}]'::jsonb, 'D', 'xv = −b / 2a = 6 / 2 = 3. yv = f(3) = 9 − 18 + 5 = −4. O vértice é (3, −4). Como a > 0, é o ponto de mínimo.', '1º ano EM'),
  ('6040efc9-914c-4c9e-abbb-8e4791c06659', null, '60198414-6d0a-4944-a35f-f70cef5507b3', 'Progressão aritmética', 'Médio', 'Autoral', null, 'Em uma PA, o primeiro termo é 3 e a razão é 4. Qual é a soma dos 10 primeiros termos?', '[{"letra":"A","texto":"150","explicacao":"Menor que o valor correto. Confira que a₁₀ = 39."},{"letra":"B","texto":"180","explicacao":"Não vem de (3 + 39) · 10 / 2."},{"letra":"C","texto":"210","explicacao":"Correta."},{"letra":"D","texto":"240","explicacao":"Maior que o valor correto. Provavelmente há erro em a₁₀ ou em n."},{"letra":"E","texto":"420","explicacao":"420 é (3 + 39) · 10, sem dividir por 2."}]'::jsonb, 'C', 'a₁₀ = 3 + 9 · 4 = 39. S₁₀ = (a₁ + a₁₀) · n / 2 = (3 + 39) · 10 / 2 = 210.', '1º ano EM'),
  ('d7115078-bf43-4998-a18a-7bd7c817b03f', null, '60198414-6d0a-4944-a35f-f70cef5507b3', 'Porcentagem', 'Médio', 'Autoral', null, 'Um produto de R$ 200,00 sofre aumento de 20% e, em seguida, desconto de 20%. Qual é o preço final?', '[{"letra":"A","texto":"R$ 200,00","explicacao":"Supõe que +20% e −20% se anulam, mas a base mudou."},{"letra":"B","texto":"R$ 192,00","explicacao":"Correta."},{"letra":"C","texto":"R$ 196,00","explicacao":"Não vem de nenhum caminho correto. Refaça 240 · 0,8."},{"letra":"D","texto":"R$ 180,00","explicacao":"Desconta R$ 60 de R$ 240, que seria 25%. O desconto é 20%."},{"letra":"E","texto":"R$ 240,00","explicacao":"É o preço depois do aumento. Falta aplicar o desconto."}]'::jsonb, 'B', 'Após o aumento: 200 · 1,2 = 240. Após o desconto: 240 · 0,8 = 192. Os percentuais incidem sobre bases diferentes, por isso não se anulam.', '1º ano EM'),
  ('beb5f8bd-4f5e-427d-a41d-acde9d89e4a9', null, '60198414-6d0a-4944-a35f-f70cef5507b3', 'Probabilidade', 'Fácil', 'Autoral', null, 'Ao lançar um dado comum de 6 faces, qual é a probabilidade de sair um número maior que 4?', '[{"letra":"A","texto":"1/2","explicacao":"Inclui o 4, o que seria “maior ou igual a 4”."},{"letra":"B","texto":"1/6","explicacao":"Considera só um resultado favorável."},{"letra":"C","texto":"2/3","explicacao":"É a probabilidade de sair 4 ou menos."},{"letra":"D","texto":"1/3","explicacao":"Correta."},{"letra":"E","texto":"5/6","explicacao":"Seria a probabilidade de NÃO sair o 6."}]'::jsonb, 'D', 'Os resultados favoráveis são 5 e 6, ou seja, 2 em 6 possíveis. P = 2/6 = 1/3.', '9º ano EF'),
  ('aacb0dae-1f9e-48d5-adcb-3797595ddceb', null, 'c8e5dbbc-216e-4db5-a7d9-33d5b7b66459', 'Classes de palavras', 'Médio', 'Autoral', null, 'Em “Ela chegou muito cedo”, as palavras “muito” e “cedo” classificam-se, respectivamente, como:', '[{"letra":"A","texto":"adjetivo e substantivo","explicacao":"Adjetivo e substantivo variam em gênero e número. Aqui nenhuma das palavras varia."},{"letra":"B","texto":"pronome indefinido e advérbio de tempo","explicacao":"“Muito” não acompanha substantivo, então não é pronome indefinido."},{"letra":"C","texto":"numeral e advérbio de lugar","explicacao":"“Muito” não é numeral, e “cedo” não indica lugar."},{"letra":"D","texto":"advérbio de modo e adjetivo","explicacao":"“Cedo” não é adjetivo, pois não caracteriza um substantivo."},{"letra":"E","texto":"advérbio de intensidade e advérbio de tempo","explicacao":"Correta."}]'::jsonb, 'E', '“Cedo” indica o momento da chegada: advérbio de tempo. “Muito” intensifica “cedo” e não varia: advérbio de intensidade. Só seria pronome ou adjetivo se acompanhasse um substantivo (muitos alunos).', '1º ano EM'),
  ('406ea4e8-12a4-4f5a-aec4-0f82d51fe016', null, 'c8e5dbbc-216e-4db5-a7d9-33d5b7b66459', 'Concordância verbal', 'Médio', 'Autoral', null, 'Assinale a frase em que a concordância verbal está de acordo com a norma-padrão.', '[{"letra":"A","texto":"Fazem dois anos que moro aqui.","explicacao":"Fazer indicando tempo é impessoal. Não vai para o plural."},{"letra":"B","texto":"Houveram muitos problemas na reunião.","explicacao":"Haver no sentido de existir é impessoal: Houve muitos problemas."},{"letra":"C","texto":"Haviam muitos alunos na sala.","explicacao":"Haver impessoal: Havia muitos alunos."},{"letra":"D","texto":"Faz dois anos que moro aqui.","explicacao":"Correta."},{"letra":"E","texto":"Devem haver soluções para esse problema.","explicacao":"O auxiliar acompanha o haver impessoal: Deve haver soluções."}]'::jsonb, 'D', 'O verbo fazer, indicando tempo decorrido, é impessoal e fica na 3ª pessoa do singular. Haver, no sentido de existir, também é impessoal: houve, havia, deve haver.', '1º ano EM'),
  ('1e66cff2-c50c-42e3-a1e3-3dab7142f0bc', null, '0e9c819e-4eb9-4976-a8d7-655bc0fbbc70', 'Escolas literárias', 'Fácil', 'Autoral', null, 'A publicação de Memórias Póstumas de Brás Cubas, de Machado de Assis, em 1881, é considerada o marco inicial de qual escola literária no Brasil?', '[{"letra":"A","texto":"Romantismo","explicacao":"O Romantismo é anterior e idealiza personagens e amores."},{"letra":"B","texto":"Naturalismo","explicacao":"O Naturalismo é contemporâneo, mas o marco da obra de Machado é o Realismo."},{"letra":"C","texto":"Parnasianismo","explicacao":"O Parnasianismo é uma escola da poesia, com foco na forma."},{"letra":"D","texto":"Realismo","explicacao":"Correta."},{"letra":"E","texto":"Modernismo","explicacao":"O Modernismo só vem no século XX, com a Semana de 1922."}]'::jsonb, 'D', 'A obra inaugura o Realismo brasileiro, com análise psicológica, ironia e crítica social. O Naturalismo é outra escola da mesma época, mais ligada ao determinismo do meio e da biologia.', '9º ano EF'),
  ('54726719-308e-458a-a55f-475408642976', null, 'd8b7eec1-c5a8-4387-a737-a12b0b7f8d5e', 'Leis de Newton', 'Fácil', 'Autoral', null, 'Um corpo de massa 4 kg sofre a ação de uma força resultante de 20 N. Qual é a aceleração que ele adquire?', '[{"letra":"A","texto":"80 m/s²","explicacao":"Multiplicou força por massa."},{"letra":"B","texto":"24 m/s²","explicacao":"Somou força e massa."},{"letra":"C","texto":"5 m/s²","explicacao":"Correta."},{"letra":"D","texto":"16 m/s²","explicacao":"Subtraiu a massa da força."},{"letra":"E","texto":"0,2 m/s²","explicacao":"Dividiu a massa pela força, ao contrário."}]'::jsonb, 'C', 'Pela 2ª lei de Newton, F = m · a. Logo a = F / m = 20 / 4 = 5 m/s².', '9º ano EF'),
  ('a257ec77-b8c7-4192-ad24-00f113c9d96b', null, 'd8b7eec1-c5a8-4387-a737-a12b0b7f8d5e', 'Eletricidade', 'Médio', 'Autoral', null, 'Um resistor de 10 Ω é percorrido por uma corrente de 2 A. Quais são a tensão entre seus terminais e a potência dissipada?', '[{"letra":"A","texto":"20 V e 20 W","explicacao":"A tensão está certa, mas a potência é U · i = 40 W."},{"letra":"B","texto":"5 V e 10 W","explicacao":"Dividiu a resistência pela corrente."},{"letra":"C","texto":"12 V e 24 W","explicacao":"Somou resistência e corrente."},{"letra":"D","texto":"40 V e 80 W","explicacao":"Usou U = R · i², mas a 1ª lei de Ohm é U = R · i."},{"letra":"E","texto":"20 V e 40 W","explicacao":"Correta."}]'::jsonb, 'E', 'U = R · i = 10 · 2 = 20 V. P = U · i = 20 · 2 = 40 W. Também dá para usar P = R · i² = 10 · 4 = 40 W.', '1º ano EM'),
  ('6bd338f6-43bd-4efb-aa2e-4ebd3610e9b7', null, 'd8b7eec1-c5a8-4387-a737-a12b0b7f8d5e', 'Cinemática', 'Médio', 'Autoral', null, 'Um carro parte do repouso com aceleração constante de 2 m/s². Após 5 s, qual é a sua velocidade e qual a distância percorrida nesse intervalo?', '[{"letra":"A","texto":"10 m/s e 50 m","explicacao":"A velocidade está certa, mas 50 m é a · t² sem dividir por 2."},{"letra":"B","texto":"5 m/s e 25 m","explicacao":"A velocidade correta é a · t = 10 m/s."},{"letra":"C","texto":"10 m/s e 25 m","explicacao":"Correta."},{"letra":"D","texto":"25 m/s e 10 m","explicacao":"Trocou as duas grandezas."},{"letra":"E","texto":"10 m/s e 10 m","explicacao":"A velocidade está certa, mas a distância não é 10 m."}]'::jsonb, 'C', 'v = a · t = 2 · 5 = 10 m/s. Δs = a · t² / 2 = 2 · 25 / 2 = 25 m.', '1º ano EM'),
  ('e24135f6-67dd-44e7-a1e7-5ae690b1596d', null, '8e02fcd1-61cf-4bd9-a555-4c076a66c31a', 'Ligações químicas', 'Fácil', 'Autoral', null, 'O cloreto de sódio (NaCl), o sal de cozinha, é formado por qual tipo de ligação química?', '[{"letra":"A","texto":"Covalente apolar","explicacao":"Haveria compartilhamento de elétrons entre ametais iguais, o que não ocorre."},{"letra":"B","texto":"Metálica","explicacao":"Ocorre entre átomos de metais, e aqui só o sódio é metal."},{"letra":"C","texto":"Iônica","explicacao":"Correta."},{"letra":"D","texto":"Covalente polar","explicacao":"É compartilhamento entre ametais diferentes. No NaCl há transferência de elétrons."},{"letra":"E","texto":"Ligação de hidrogênio","explicacao":"É uma interação entre moléculas, não a ligação que forma o NaCl."}]'::jsonb, 'C', 'O sódio (metal) transfere um elétron ao cloro (ametal). Surgem os íons Na⁺ e Cl⁻, que se atraem: é uma ligação iônica.', '9º ano EF'),
  ('e14efe46-1b59-4381-a643-c4c847fd4215', null, '8e02fcd1-61cf-4bd9-a555-4c076a66c31a', 'Mol e massa molar', 'Médio', 'Autoral', null, 'Quantos mols de moléculas há em 36 g de água (H₂O)? Dados: H = 1 g/mol e O = 16 g/mol.', '[{"letra":"A","texto":"4 mol","explicacao":"Dividiu por 9, que não é a massa molar da água."},{"letra":"B","texto":"0,5 mol","explicacao":"Inverteu a divisão: 18 / 36."},{"letra":"C","texto":"1 mol","explicacao":"1 mol de água tem 18 g, e não 36 g."},{"letra":"D","texto":"36 mol","explicacao":"Tratou a massa em gramas como se fosse a quantidade em mols."},{"letra":"E","texto":"2 mol","explicacao":"Correta."}]'::jsonb, 'E', 'M(H₂O) = 2 · 1 + 16 = 18 g/mol. n = m / M = 36 / 18 = 2 mol.', '1º ano EM'),
  ('c8f4e189-84c6-4698-aa56-b4e3faa15528', null, '8e02fcd1-61cf-4bd9-a555-4c076a66c31a', 'pH e acidez', 'Médio', 'Autoral', null, 'Uma solução aquosa a 25 °C tem concentração de íons H⁺ igual a 10⁻³ mol/L. Qual é o seu pH e o seu caráter?', '[{"letra":"A","texto":"pH 11, ácido","explicacao":"pH 11 seria o pOH, e uma solução com pH 11 seria básica."},{"letra":"B","texto":"pH 3, básico","explicacao":"O pH está certo, mas abaixo de 7 a solução é ácida."},{"letra":"C","texto":"pH 7, neutro","explicacao":"pH 7 exigiria [H⁺] = 10⁻⁷ mol/L."},{"letra":"D","texto":"pH 3, ácido","explicacao":"Correta."},{"letra":"E","texto":"pH −3, ácido","explicacao":"Esqueceu o sinal negativo da definição pH = −log[H⁺]."}]'::jsonb, 'D', 'pH = −log[H⁺] = −log 10⁻³ = 3. A 25 °C, pH menor que 7 indica solução ácida.', '1º ano EM'),
  ('28a938b9-d490-4834-ab6d-795cacc517d7', null, '2067eafe-b976-41af-ae69-f64282afcc0f', 'Citologia', 'Fácil', 'Autoral', null, 'Qual organela é a principal responsável pela produção de ATP na respiração celular?', '[{"letra":"A","texto":"Ribossomo","explicacao":"O ribossomo produz proteínas."},{"letra":"B","texto":"Lisossomo","explicacao":"O lisossomo faz digestão intracelular."},{"letra":"C","texto":"Complexo golgiense","explicacao":"O complexo golgiense modifica e empacota substâncias."},{"letra":"D","texto":"Cloroplasto","explicacao":"O cloroplasto faz fotossíntese e existe em plantas e algas."},{"letra":"E","texto":"Mitocôndria","explicacao":"Correta."}]'::jsonb, 'E', 'A mitocôndria realiza as etapas finais da respiração celular aeróbia e produz a maior parte do ATP. O cloroplasto atua na fotossíntese.', '9º ano EF'),
  ('81e21e8a-30b9-4600-af3f-3218ab5d5b71', null, '2067eafe-b976-41af-ae69-f64282afcc0f', 'Genética', 'Médio', 'Autoral', null, 'Do cruzamento entre dois indivíduos heterozigotos (Aa × Aa), qual é a probabilidade de nascer um descendente com genótipo aa?', '[{"letra":"A","texto":"1/2","explicacao":"1/2 é a probabilidade de Aa."},{"letra":"B","texto":"3/4","explicacao":"3/4 é a probabilidade do fenótipo dominante."},{"letra":"C","texto":"1/4","explicacao":"Correta."},{"letra":"D","texto":"0","explicacao":"Seria impossível apenas se um dos pais não tivesse o alelo a."},{"letra":"E","texto":"1","explicacao":"Só ocorreria se os dois pais fossem aa."}]'::jsonb, 'C', 'Aa × Aa gera 1/4 AA, 2/4 Aa e 1/4 aa. A probabilidade de aa é 1/4.', '1º ano EM'),
  ('db977cd3-e8df-40e6-a199-4027de29794d', null, '2067eafe-b976-41af-ae69-f64282afcc0f', 'Ecologia', 'Fácil', 'Autoral', null, 'Em uma cadeia alimentar, os produtores são os organismos que:', '[{"letra":"A","texto":"alimentam-se de outros animais","explicacao":"Isso descreve os consumidores carnívoros."},{"letra":"B","texto":"decompõem a matéria orgânica de seres mortos","explicacao":"Isso descreve os decompositores."},{"letra":"C","texto":"produzem o próprio alimento, em geral por fotossíntese","explicacao":"Correta."},{"letra":"D","texto":"dependem exclusivamente dos herbívoros","explicacao":"Os produtores não dependem de outros seres para obter alimento."},{"letra":"E","texto":"alimentam-se somente de plantas","explicacao":"Isso descreve os herbívoros."}]'::jsonb, 'C', 'Produtores são autótrofos: transformam substâncias inorgânicas em matéria orgânica, em geral pela fotossíntese. Plantas, algas e algumas bactérias são exemplos.', '9º ano EF'),
  ('1211f134-876e-456a-a8dd-02564e7112ca', null, 'ade6b967-7111-4297-a03b-41579f1c7f6d', 'Revolução Industrial', 'Fácil', 'Autoral', null, 'A Revolução Industrial teve início em qual país e em qual século?', '[{"letra":"A","texto":"Estados Unidos, século XIX","explicacao":"Os Estados Unidos se industrializaram com mais força no século XIX."},{"letra":"B","texto":"França, século XVII","explicacao":"A França não foi o ponto de partida do processo."},{"letra":"C","texto":"Alemanha, século XIX","explicacao":"A Alemanha industrializou-se mais tarde, no século XIX."},{"letra":"D","texto":"Inglaterra, século XVIII","explicacao":"Correta."},{"letra":"E","texto":"Inglaterra, século XVI","explicacao":"O século XVI é anterior ao processo, que começou no XVIII."}]'::jsonb, 'D', 'A Revolução Industrial começou na Inglaterra, na segunda metade do século XVIII, com a mecanização da produção têxtil e o uso da máquina a vapor.', '9º ano EF'),
  ('09f94aea-8cd2-401e-ad7c-243dc54f1c57', null, 'ade6b967-7111-4297-a03b-41579f1c7f6d', 'Brasil Império', 'Fácil', 'Autoral', null, 'A Lei Áurea, que aboliu a escravidão no Brasil, foi assinada em:', '[{"letra":"A","texto":"1822","explicacao":"1822 é o ano da Independência."},{"letra":"B","texto":"1850","explicacao":"1850 é o ano da Lei Eusébio de Queirós, que proibiu o tráfico de africanos escravizados."},{"letra":"C","texto":"1871","explicacao":"1871 é o ano da Lei do Ventre Livre."},{"letra":"D","texto":"1888","explicacao":"Correta."},{"letra":"E","texto":"1889","explicacao":"1889 é o ano da Proclamação da República."}]'::jsonb, 'D', 'A Lei Áurea é de 13 de maio de 1888. Antes dela vieram a Lei Eusébio de Queirós (1850), que acabou com o tráfico, e a Lei do Ventre Livre (1871).', '9º ano EF'),
  ('8ec17966-6d5c-4922-ad84-e79678f39ceb', null, '1aaa1633-d43e-4389-a3c4-79cd1e430013', 'Biomas brasileiros', 'Fácil', 'Autoral', null, 'Qual bioma brasileiro é marcado por clima semiárido e vegetação adaptada à seca?', '[{"letra":"A","texto":"Pampa","explicacao":"O Pampa tem campos e clima mais frio no sul."},{"letra":"B","texto":"Caatinga","explicacao":"Correta."},{"letra":"C","texto":"Pantanal","explicacao":"O Pantanal é uma planície alagável."},{"letra":"D","texto":"Amazônia","explicacao":"A Amazônia tem clima equatorial quente e úmido."},{"letra":"E","texto":"Mata Atlântica","explicacao":"A Mata Atlântica é mais úmida e ocupa o litoral."}]'::jsonb, 'B', 'A Caatinga predomina no sertão nordestino, com chuvas escassas e irregulares e plantas adaptadas à seca, como cactos e arbustos de galhos retorcidos.', '9º ano EF'),
  ('1961e1b4-d251-406d-a622-689ad9540fc9', null, '1aaa1633-d43e-4389-a3c4-79cd1e430013', 'População e urbanização', 'Fácil', 'Autoral', null, 'O deslocamento de população do campo para a cidade, intensificado no Brasil a partir da segunda metade do século XX, é chamado de:', '[{"letra":"A","texto":"migração pendular","explicacao":"Migração pendular é o deslocamento diário entre casa e trabalho ou escola."},{"letra":"B","texto":"imigração","explicacao":"Imigração é a entrada de pessoas em outro país."},{"letra":"C","texto":"transumância","explicacao":"Transumância é o deslocamento sazonal de rebanhos."},{"letra":"D","texto":"emigração","explicacao":"Emigração é a saída de pessoas do próprio país."},{"letra":"E","texto":"êxodo rural","explicacao":"Correta."}]'::jsonb, 'E', 'Êxodo rural é a saída de pessoas do campo em direção às cidades. No Brasil ele acompanhou a industrialização e a mecanização do campo.', '9º ano EF'),
  ('7a65ee42-c67e-4501-a794-60f0c01b975a', null, '6fc39871-7e00-45a1-aa7f-6de12b101dee', 'Filosofia antiga', 'Fácil', 'Autoral', null, 'O método de Sócrates, que usa perguntas para levar o interlocutor a refletir e a “dar à luz” as próprias ideias, é conhecido como:', '[{"letra":"A","texto":"dúvida metódica","explicacao":"A dúvida metódica é o procedimento de Descartes."},{"letra":"B","texto":"empirismo","explicacao":"Empirismo defende que o conhecimento vem da experiência."},{"letra":"C","texto":"dialética marxista","explicacao":"Dialética marxista é uma teoria sobre as contradições da sociedade."},{"letra":"D","texto":"maiêutica","explicacao":"Correta."},{"letra":"E","texto":"cogito","explicacao":"O cogito é o “penso, logo existo” de Descartes."}]'::jsonb, 'D', 'Maiêutica significa “arte de partejar”: por meio de perguntas, Sócrates conduzia o interlocutor a descobrir o conhecimento por conta própria.', '9º ano EF'),
  ('b75605cf-9676-48b6-affc-2f609c4bec5d', null, 'd1b21986-7759-46e5-ade8-fcea04084748', 'Clássicos da Sociologia', 'Médio', 'Autoral', null, 'Para o sociólogo Émile Durkheim, “fato social” é:', '[{"letra":"A","texto":"qualquer ação realizada por um indivíduo isolado","explicacao":"Uma ação individual isolada não é fato social."},{"letra":"B","texto":"uma opinião pessoal sem influência coletiva","explicacao":"O fato social é coletivo e vai além da opinião pessoal."},{"letra":"C","texto":"uma maneira de agir, pensar e sentir exterior ao indivíduo, que exerce sobre ele uma força de coerção","explicacao":"Correta."},{"letra":"D","texto":"apenas aquilo que está previsto em lei","explicacao":"Nem todo fato social está em lei. Costumes também são fatos sociais."},{"letra":"E","texto":"um fenômeno natural, sem relação com a sociedade","explicacao":"O fato social é próprio da vida em sociedade."}]'::jsonb, 'C', 'Para Durkheim, fatos sociais são exteriores aos indivíduos, são gerais na sociedade e exercem coerção sobre eles. Exemplos: costumes, regras morais e religiosas.', '1º ano EM'),
  ('35e385b2-8ffa-4f54-abf0-7dd7a3bbde61', null, '9fb84ab9-66aa-4284-a4cc-603bddbe4554', 'Simple present', 'Fácil', 'Autoral', null, 'Choose the correct option: “She ___ to school every day.”', '[{"letra":"A","texto":"go","explicacao":"Com she, o verbo precisa da terminação -s."},{"letra":"B","texto":"going","explicacao":"“Going” exigiria o auxiliar: she is going."},{"letra":"C","texto":"gone","explicacao":"“Gone” é o particípio passado: she has gone."},{"letra":"D","texto":"is go","explicacao":"Mistura o auxiliar is com o verbo no infinitivo."},{"letra":"E","texto":"goes","explicacao":"Correta."}]'::jsonb, 'E', 'Para hábitos usamos o simple present. Na 3ª pessoa do singular (she, he, it), o verbo ganha -s ou -es: she goes.', '9º ano EF'),
  ('6bae4dcf-381b-4662-a676-f9fe59bf0b7e', null, '9fb84ab9-66aa-4284-a4cc-603bddbe4554', 'Present perfect', 'Médio', 'Autoral', null, 'Complete the sentence: “They ___ studying English since 2022.”', '[{"letra":"A","texto":"are","explicacao":"O present continuous não se combina com since."},{"letra":"B","texto":"were","explicacao":"O past continuous indica ação encerrada no passado."},{"letra":"C","texto":"has been","explicacao":"Has been é para he, she e it. Com they, usa-se have."},{"letra":"D","texto":"did","explicacao":"O passado simples não se combina com a forma -ing."},{"letra":"E","texto":"have been","explicacao":"Correta."}]'::jsonb, 'E', 'Since + ponto no passado, com ação que continua até agora, pede o present perfect continuous: have/has been + verbo com -ing. Com “they”, usa-se have.', '1º ano EM'),
  ('c559de89-1065-4876-a8cc-bf2dba8f1e11', null, '412de6f0-5515-46b2-a56c-ea585a2f992d', 'Movimentos artísticos', 'Fácil', 'Autoral', null, 'Qual movimento artístico, associado a Pablo Picasso e Georges Braque, representa os objetos por vários ângulos ao mesmo tempo, com formas geométricas?', '[{"letra":"A","texto":"Barroco","explicacao":"O Barroco destaca contrastes de luz e sombra e a dramaticidade."},{"letra":"B","texto":"Surrealismo","explicacao":"O Surrealismo explora o sonho e o inconsciente."},{"letra":"C","texto":"Impressionismo","explicacao":"O Impressionismo captura a impressão da luz e da cor."},{"letra":"D","texto":"Cubismo","explicacao":"Correta."},{"letra":"E","texto":"Renascimento","explicacao":"O Renascimento valoriza perspectiva, proporção e realismo."}]'::jsonb, 'D', 'O Cubismo decompõe os objetos em formas geométricas e os mostra de vários pontos de vista ao mesmo tempo.', '9º ano EF'),
  ('4cf247f6-7490-4dc5-a0ef-d6232dc38062', null, 'c8c2c8c3-a196-45e2-af33-27ab7955693a', 'Estrutura da redação', 'Fácil', 'Autoral', null, 'Em uma redação dissertativo-argumentativa, onde normalmente se apresenta a proposta de intervenção?', '[{"letra":"A","texto":"Na introdução, junto com a tese","explicacao":"A introdução apresenta o tema e a tese."},{"letra":"B","texto":"No título do texto","explicacao":"O título não comporta uma proposta completa."},{"letra":"C","texto":"Na conclusão","explicacao":"Correta."},{"letra":"D","texto":"Em uma nota de rodapé","explicacao":"A redação não usa notas de rodapé."},{"letra":"E","texto":"No primeiro parágrafo de desenvolvimento","explicacao":"O desenvolvimento aprofunda os argumentos."}]'::jsonb, 'C', 'A proposta de intervenção fecha o texto: retoma a tese e indica agente, ação, meio, finalidade e detalhamento. Em provas como a redação do Enem, ela faz parte de uma das competências avaliadas.', '9º ano EF')
